{
  "name": "VISA串口通信组件",
  "name_en": "VISA Serial Communication Component",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，用于通过VISA串口会话与实验仪器进行通用消息通信。它提供会话初始化、关闭、连接状态检查以及原始字节收发功能，通常作为具体仪器驱动的基础层使用，而不是某一台特定硬件仪器本身。",
  "description_en": "A non-physical software communication component for generic message-based communication with laboratory instruments over a VISA serial session. It provides session initialization, shutdown, connection-state checking, and raw byte send/receive functions, typically serving as a base layer for specific instrument drivers rather than representing a particular hardware instrument itself.",
  "actions": [
    {
      "action_name": "auto-raw_recv",
      "description": "从VISA串口会话接收原始字节数据。",
      "description_en": "Receive raw byte data from the VISA serial session."
    },
    {
      "action_name": "auto-raw_send",
      "description": "通过VISA串口会话发送原始字节数据。",
      "description_en": "Send raw byte data through the VISA serial session."
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化并打开VISA串口通信会话。",
      "description_en": "Initialize and open the VISA serial communication session."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭并释放VISA串口通信会话。",
      "description_en": "Close and release the VISA serial communication session."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查VISA串口通信会话是否已打开。",
      "description_en": "Check whether the VISA serial communication session is open."
    }
  ],
  "tag_hints": [
    "VISA serial communication",
    "instrument session management",
    "raw byte I/O",
    "serial port instruments",
    "message-based communication",
    "lab instrument software component"
  ]
}

